def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict):
        raise Blocked("TC-033 前提查询失败：GET /communities 应返回 HTTP 200 和 JSON 对象")
    if responseBody.get("code") != 0 or not isinstance(responseBody.get("data"), list):
        raise Blocked("TC-033 前提查询失败：GET /communities 应返回业务码 0 和社区数组")
    raise Blocked("TC-033 缺少创建、停用社区及查询停用状态的公开 HTTP 接口；无法独立构造并确认停用社区，未验证切换拒绝及原社区不变")
